diff --git a/src/knownhost.c b/src/knownhost.c
index 2bd41de..5ce5907 100644
--- a/src/knownhost.c
+++ b/src/knownhost.c
@@ -458,7 +458,7 @@ static int knownhost_parse_ipv6(const char *src, size_t len,
         if(p < end && *p == '.') {
             unsigned char ipv4[4];

-            if(count > 6 || !knownhost_parse_ipv4(part, end, ipv4))
+            if(!knownhost_parse_ipv4(part, end, ipv4))
                 return 0;

             words[count++] =
@@ -514,6 +514,28 @@ static int knownhost_parse_ipv6(const char *src, size_t len,
     return 1;
 }

+/* Reject spans that cannot be IPv6 literals before running the full
+   parser: a colon-separated list of at most eight groups, where an
+   embedded IPv4 tail counts as the final two groups. */
+static int knownhost_ipv6_groups_ok(const char *src, size_t len)
+{
+    size_t groups = 1;
+    size_t i;
+    int tail = 0;
+
+    for(i = 0; i < len; i++) {
+        if(src[i] == ':')
+            groups++;
+        else if(src[i] == '.')
+            tail = 1;
+    }
+
+    if(tail)
+        groups++;
+
+    return groups <= 8;
+}
+
 static int knownhost_ipv6_part(const char *host, const char **address,
                                size_t *address_len, const char **suffix)
 {
@@ -541,7 +563,7 @@ static int knownhost_ipv6_part(const char *host, const char **address,
         *suffix = host + *address_len;
     }

-    return 1;
+    return knownhost_ipv6_groups_ok(*address, *address_len);
 }

 static int knownhost_plain_match(const char *host, const char *known)

